select case when year(c.signup_date) < 2024 then 'before_2024' when year(c.signup_date) = 2024 then '2024' else 'after_2024' end as signup_cohort, sort_array(collect_set(s.status)) as status_list, round(stddev(s.monthly_fee), 2) as stddev_monthly_fee from subscriptions s join customers c on c.id = s.customer_id group by case when year(c.signup_date) < 2024 then 'before_2024' when year(c.signup_date) = 2024 then '2024' else 'after_2024' end order by stddev_monthly_fee desc
